from __future__ import annotations

from fractions import Fraction
from typing import Dict, Iterator, List, Sequence


def compositions(n: int) -> Iterator[List[int]]:
    """All 2^(n-1) tie profiles of n observations (bitmask of block cuts)."""
    for mask in range(2 ** (n - 1)):
        prof: List[int] = []
        run = 1
        for i in range(n - 1):
            if (mask >> i) & 1:
                prof.append(run)
                run = 1
            else:
                run += 1
        prof.append(run)
        yield prof


def midranks(p: Sequence[int]) -> List[Fraction]:
    out: List[Fraction] = []
    s = 0
    for l in p:
        out.extend([Fraction(2 * s + l + 1, 2)] * l)
        s += l
    return out


def tie_factor(p: Sequence[int]) -> Fraction:
    n = sum(p)
    return 1 - Fraction(sum(l ** 3 - l for l in p), n ** 3 - n)


def cuts(p: Sequence[int]) -> set[int]:
    out, s = set(), 0
    for l in p[:-1]:
        s += l
        out.add(s)
    return out


def census(n: int) -> Dict[str, int]:
    """Exhaustive exact census of all ordered profile pairs of size n."""
    profs = list(compositions(n))
    D = Fraction(n ** 3 - n, 12)
    c = Fraction(n + 1, 2)
    res = {"pairs": 0, "product_equality": 0, "ratio_violations": 0,
           "nested": 0, "nested_ratio_equality": 0}
    for L in profs:
        RL = midranks(L)
        for M in profs:
            RM = midranks(M)
            r = sum((a - c) * (b - c) for a, b in zip(RL, RM)) / D
            fl, fm = tie_factor(L), tie_factor(M)
            res["pairs"] += 1
            res["product_equality"] += (r * r == fl * fm)
            if fl > 0 and fm > 0:
                rc2 = r * r / (fl * fm)
                bound = min(fl, fm) / max(fl, fm)
                res["ratio_violations"] += rc2 > bound
                if cuts(L) <= cuts(M) or cuts(M) <= cuts(L):
                    res["nested"] += 1
                    res["nested_ratio_equality"] += rc2 == bound
    return res


if __name__ == "__main__":
    for n in range(2, 8):
        r = census(n)
        print(n, r, "predicted equality count:", 3 * 2 ** (n - 1) - 2)

from __future__ import annotations

from typing import Dict, List, Sequence


def tie_factor(p: Sequence[int]) -> float:
    n = sum(p)
    return 1 - sum(l ** 3 - l for l in p) / (n ** 3 - n)


def certificate(r: float, corrected: bool) -> float:
    """Lower bound on the response tie factor implied by an observed rho r > 0
    when the dial is untied: f(M) >= r (textbook) or f(M) >= r^2 (corrected)."""
    if not 0 < r <= 1:
        raise ValueError("observed coefficient must lie in (0, 1]")
    return r * r if corrected else r


def screen(r: float, candidates: List[Sequence[int]]) -> List[Dict[str, object]]:
    """Report which candidate response profiles are compatible with r."""
    out = []
    for M in candidates:
        f = tie_factor(M)
        out.append({"profile": list(M), "f": round(f, 6),
                    "textbook_ok": f >= certificate(r, False),
                    "corrected_ok": f >= certificate(r, True)})
    return out


